const cfg=$('CONFIG - EDIT ME').first().json;
const first=$input.first().json;
const html=typeof first==='string'?first:(first.body||first.data||first.html||JSON.stringify(first));
const decode=s=>String(s||'').replace(/&amp;/g,'&').replace(/&#x27;|&#39;/g,"'").replace(/&quot;/g,'\"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
const out=[];
const blocks=String(html).split(/<li>/i).slice(1);
for(const b of blocks){
 const id=(b.match(/data-entity-urn=\"urn:li:jobPosting:(\d+)/i)||[])[1]||'';
 const href=decode((b.match(/base-card__full-link[^>]*href=\"([^\"]+)/i)||[])[1]||'');
 const title=decode((b.match(/base-search-card__title[^>]*>([\s\S]*?)<\//i)||[])[1]||'');
 const company=decode((b.match(/base-search-card__subtitle[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/i)||[])[1]||(b.match(/base-search-card__subtitle[^>]*>([\s\S]*?)<\//i)||[])[1]||'');
 const location=decode((b.match(/job-search-card__location[^>]*>([\s\S]*?)<\//i)||[])[1]||'Remote');
 const dt=(b.match(/datetime=\"([^\"]+)/i)||[])[1]||'';
 if(title&&href) out.push({json:{id:String(id||href),title,company,location,jobType:'Remote',salary:'',tags:[],publishedAt:dt,url:href.split('?')[0],source:'LinkedIn',description:''}});
}
return out;

