const cfg=$('CONFIG - EDIT ME').first().json;
const keywords=String(cfg.keywords||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);
const allowed=String(cfg.allowedLocations||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);
const maxTotal=Number(cfg.maxJobsPerRun||30);
const maxPerCategory=Number(cfg.maxJobsPerCategory||3);
const strip=s=>String(s||'').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/\s+/g,' ').trim();
const locOk=loc=>{const l=String(loc||'remote').toLowerCase(); return !allowed.length||allowed.some(x=>l.includes(x))||l.includes('remote')||l.includes('worldwide')||l.includes('anywhere');};
const keywordOk=j=>{const h=[j.title,j.company,j.location,(j.tags||[]).join(' '),strip(j.description)].join(' ').toLowerCase(); return !keywords.length||keywords.some(k=>h.includes(k));};
const classify=j=>{const h=[j.title,(j.tags||[]).join(' '),strip(j.description)].join(' ').toLowerCase(); const rules=[
['Backend',/backend|back-end|node\.?js|nestjs|golang|go engineer|api engineer/],
['Frontend',/frontend|front-end|react|next\.?js|vue|angular|web ui/],
['Full Stack',/full[ -]?stack|fullstack/],
['Mobile',/mobile|android|ios|flutter|react native/],
['DevOps / Cloud',/devops|platform engineer|cloud engineer|site reliability|\bsre\b|kubernetes|infrastructure/],
['QA / Testing',/quality assurance|\bqa\b|test engineer|automation engineer|sdet/],
['Data',/data engineer|data analyst|data scientist|analytics engineer|machine learning|ml engineer/],
['Security',/security engineer|cybersecurity|cyber security|application security|cloud security|soc analyst/],
['Product',/product manager|product engineer|technical product/],
['Design / UX',/ui[ \/-]?ux|ux designer|product designer|ui designer/],
['IT / Support',/it support|technical support|support engineer|systems administrator|sysadmin/],
['Software Engineer',/software engineer|software developer|developer|programmer/]
]; for(const [name,re] of rules) if(re.test(h)) return name; return 'Other Tech';};
const juniorOnly=cfg.juniorOnly!==false;
const juniorPositive=/\b(junior|jr\.?|entry[ -]?level|graduate|new grad|fresh graduate|associate|early career|trainee|apprentice|intern(ship)?|0\s*[-–]\s*2 years?|1\s*[-–]\s*2 years?)\b/i;
const seniorNegative=/\b(senior|sr\.?|staff|principal|lead|manager|director|head of|architect|vp|vice president)\b/i;
const juniorOk=j=>{
  if(!juniorOnly) return true;
  const title=String(j.title||'');
  const h=[title,(j.tags||[]).join(' '),strip(j.description)].join(' ');
  if(seniorNegative.test(title)) return false;
  return juniorPositive.test(h);
};
const seen=new Set(); const rows=[];
for(const i of $input.all()){const j=i.json||{}; if(!j.title||!j.url||!keywordOk(j)||!locOk(j.location)||!juniorOk(j)) continue; const k=[j.title,j.company].join('|').toLowerCase().replace(/[^a-z0-9|]+/g,' ').trim(); if(seen.has(k)) continue; seen.add(k); j.category=classify(j); rows.push(i);}
rows.sort((a,b)=>new Date(b.json.publishedAt||0)-new Date(a.json.publishedAt||0));
const buckets={}; for(const i of rows){(buckets[i.json.category]??=[]).push(i);}
const order=['Backend','Frontend','Full Stack','Mobile','DevOps / Cloud','QA / Testing','Data','Security','Product','Design / UX','IT / Support','Software Engineer','Other Tech'];
const result=[]; let round=0;
while(result.length<maxTotal){let added=false; for(const cat of order){const arr=buckets[cat]||[]; if(round<maxPerCategory && arr[round]){result.push(arr[round]); added=true; if(result.length>=maxTotal) break;}} if(!added||round>=maxPerCategory-1) break; round++;}
if(result.length<maxTotal){const used=new Set(result.map(x=>x.json.source+'|'+x.json.id)); for(const i of rows){const k=i.json.source+'|'+i.json.id; if(used.has(k)) continue; result.push(i); used.add(k); if(result.length>=maxTotal) break;}}
return result;

const esc=v=>String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
return $input.all().map(item=>{const j=item.json; const salary=j.salary?`
💰 <b>Salary:</b> ${esc(j.salary)}`:''; const published=j.publishedAt?esc(String(j.publishedAt)):'Unknown'; const msg=`🧭 <b>NEW JOB — ${esc(j.category||'Tech')}</b>

💼 <b>${esc(j.title)}</b>
🏢 ${esc(j.company||'Unknown company')}
📍 ${esc(j.location||'Remote')}
🧾 ${esc(j.jobType||'Not specified')}${salary}

🕒 <b>Published:</b> ${published}
🌐 <b>Source:</b> ${esc(j.source)}

🔗 <a href="${esc(j.url)}">Open & Apply</a>`; return {json:{...j,telegramMessage:msg}};});
